'use strict';
(()=>{
 const G=TerrainGenerators,$=id=>document.getElementById(id);let comparison=false,results=[];
 const total=Object.keys(G.algorithms).length;
 for(const [id,a]of Object.entries(G.algorithms)){const option=document.createElement('option');option.value=id;option.textContent=a.name;$('algorithm').append(option);}
 function polygon(c){const cx=325+HexMap.x(c.x,c.y),cy=300+HexMap.y(c.y);return Array.from({length:6},(_,i)=>{const a=(30+i*60)*Math.PI/180;return [cx+Math.cos(a)*HexMap.RADIUS,cy+Math.sin(a)*HexMap.RADIUS].join(',');}).join(' ');}
 function draw(result){const set=new Set(result.cells.map(G.key)),card=document.createElement('article');card.className='map';const title=document.createElement('button');title.textContent=G.algorithms[result.algorithm].name+(result.islandStyle?' · '+result.islandStyle:'');title.title='点击单独查看';title.onclick=()=>{$('algorithm').value=result.algorithm;comparison=false;render();};card.append(title);
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','-70 20 790 560');svg.setAttribute('role','img');svg.setAttribute('aria-label',`${G.algorithms[result.algorithm].name}，${result.stats.area}格，${result.stats.components}个连通区域`);
 svg.innerHTML=G.cells.map(c=>`<polygon points="${polygon(c)}" fill="${set.has(G.key(c))?'#f2f3ef':'none'}" stroke="${set.has(G.key(c))?'#9ca6aa':'#394650'}" stroke-width="${set.has(G.key(c))?1.3:.8}" ${set.has(G.key(c))?'':'stroke-dasharray="3 4"'}/>`).join('')+'<path d="M319 350h12m-6-6v12" stroke="#93d3b2" stroke-width="2"/>';
 card.append(svg);const stats=document.createElement('div');stats.className='stats';stats.innerHTML=`<span><b>${result.stats.area}</b>格</span>${result.rhythm?`<span><b>${result.rhythm.regionCount}</b>个起点 / ${result.rhythm.landmassCount}片主体 / ${result.rhythm.corridors.length}条走廊</span><span>主体 ${result.rhythm.islandSizes.join(" / ")}格</span><span>岛体半径≤2格</span><span>走廊 ${result.rhythm.corridors.map(c=>c.width).join(" / ")||"无"}格</span>`:''}<span><b>${result.stats.components}</b>连通区</span><span><b>${result.stats.thin}</b>窄格¹</span><span><b>${result.changed}</b>修复格</span><span>原始 ${result.rawCount}格 / ${result.rawComponents}区</span>`;stats.title='¹ 窄格：相邻地板不超过2格的地块；修复格：原始结果与最终结果的增删格总数。';card.append(stats);return card;}
 function render(){
  const automatic=$('seedOnly').checked,parameters=automatic?G.parametersFromSeed($('seed').value):null;$('parameters').hidden=automatic;
  if(parameters){for(const field of ['count','variation','regionCount','regionSpacing','sizeVariation','sides','bays','roughness','islandMode'])$(field).value=String(parameters[field]);$('corridorWidth').value='1-3';$('connected').checked=true;}
  $('connected').disabled=automatic;$('seedSummary').hidden=!automatic;$('seedSummary').textContent=parameters?`种子自动决定：${parameters.count}格预算 · ${parameters.regionCount}个生长中心 · 大小差异${parameters.sizeVariation} · 间距${parameters.regionSpacing} · 边缘变化${parameters.variation} · 走廊1/2/3格概率75%/20%/5% · 至少两片明显岛体 · 每岛半径≤2格。`:'';
  const id=$('algorithm').value,a=G.algorithms[id];$('description').textContent=a.desc;$('variationHelp').textContent=a.param;$('countLabel').textContent=id==='rhythm'?'参考面积':'目标面积';$('countValue').textContent=$('count').value+' 格';$('variationValue').textContent=$('variation').value;$('variationLabel').textContent=id==='island'?'侵蚀深度':id==='rhythm'?'块面边缘变化':'形态参数';$('rhythmControls').hidden=id!=='rhythm'&&!comparison;for(const field of ['regionCount','regionSpacing','sizeVariation'])$(field+'Value').textContent=$(field).value;$('islandControls').hidden=id!=='island'&&!comparison;for(const field of ['sides','bays','roughness'])$(field+'Value').textContent=$(field).value;$('mapTitle').textContent=comparison?'同一种子 · '+total+'种形状':a.name;$('compare').textContent=comparison?'返回单图查看':total+'种算法同屏比较';const options={count:+$('count').value,variation:+$('variation').value,seed:$('seed').value,connected:$('connected').checked,islandMode:$('islandMode').value,sides:+$('sides').value,bays:+$('bays').value,roughness:+$('roughness').value,regionCount:+$('regionCount').value,regionSpacing:+$('regionSpacing').value,sizeVariation:+$('sizeVariation').value,corridorWidthMin:+$('corridorWidth').value.split('-')[0],corridorWidthMax:+($('corridorWidth').value.split('-')[1]||$('corridorWidth').value)};results=(comparison?Object.keys(G.algorithms):[id]).map(k=>automatic?{...G.generate(k,parameters),recipeVersion:5,parameters}:{...G.generate(k,options)});$('boards').classList.toggle('comparison',comparison);$('boards').replaceChildren(...results.map(draw));$('notice').textContent='¹ 窄格：六邻居中地板≤2格。修复格数包括新增和删除。';}
 for(const id of ['seedOnly','algorithm','count','variation','connected','islandMode','sides','bays','roughness','regionCount','regionSpacing','corridorWidth','sizeVariation'])$(id).addEventListener('input',render);$('seed').addEventListener('change',render);$('seed').addEventListener('keydown',e=>{if(e.key==='Enter')render();});$('rerun').onclick=render;$('generate').onclick=()=>{$('seed').value='map-'+crypto.getRandomValues(new Uint32Array(1))[0].toString(36);render();};$('compare').onclick=()=>{comparison=!comparison;render();};$('export').onclick=()=>{const data={version:1,grid:{columns:13,rows:11,minX:-6,maxX:6,minY:-5,maxY:5},maps:results},url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='hex-terrain-maps.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('notice').textContent='地图坐标与生成参数已导出。';};$('algorithm').value='rhythm';$('count').value='55';$('variation').value='35';render();
})();
